// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title TenantPipelineRegistry
 * @notice Multi-tenant CI/CD pipeline registry for Solidity contract deployments
 * @dev Each tenant has isolated deployment slots; pipeline actions require auth
 */
contract TenantPipelineRegistry is AccessControl {
    using ECDSA for bytes32;

    bytes32 public constant DEPLOYER_ROLE = keccak256("DEPLOYER_ROLE");
    bytes32 public constant TENANT_ADMIN_ROLE = keccak256("TENANT_ADMIN_ROLE");

    struct PipelineAction {
        address tenant;
        bytes32 artifactHash;
        uint256 nonce;
        uint256 deadline;
        bytes32 pipelineId;
    }

    struct TenantConfig {
        address admin;
        address deployer;
        bytes32 secretHash; // keccak256 of tenant's pipeline secret
        uint256 nonce;
        bool active;
    }

    mapping(bytes32 => TenantConfig) public tenants;
    mapping(bytes32 => mapping(bytes32 => address)) public deployments;
    mapping(bytes32 => bool) public usedActionHashes;

    event TenantRegistered(bytes32 indexed tenantId, address admin);
    event PipelineExecuted(bytes32 indexed tenantId, bytes32 indexed pipelineId, bytes32 artifactHash);
    event DeploymentRecorded(bytes32 indexed tenantId, bytes32 indexed artifactHash, address deployedAt);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function registerTenant(
        bytes32 tenantId,
        address admin,
        address deployer,
        bytes32 secretHash
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(!tenants[tenantId].active, "Tenant exists");
        tenants[tenantId] = TenantConfig({
            admin: admin,
            deployer: deployer,
            secretHash: secretHash,
            nonce: 0,
            active: true
        });
        _grantRole(TENANT_ADMIN_ROLE, admin);
        _grantRole(DEPLOYER_ROLE, deployer);
        emit TenantRegistered(tenantId, admin);
    }

    /**
     * @notice Computes the action digest for pipeline authentication
     * @dev The digest binds the action to this contract and chain
     */
    function computeActionDigest(PipelineAction memory action) public view returns (bytes32) {
        bytes32 structHash = keccak256(abi.encode(
            action.tenant,
            action.artifactHash,
            action.nonce,
            action.deadline,
            action.pipelineId
        ));
        // Domain separation with contract address and chain id
        return keccak256(abi.encodePacked(
            "\x19\x01",
            _domainSeparator(),
            structHash
        ));
    }

    function _domainSeparator() internal view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256("TenantPipelineRegistry"),
            keccak256("1"),
            block.chainid,
            address(this)
        ));
    }

    /**
     * @notice Validates pipeline action using the tenant's secret hash
     * @dev Uses hash comparison for CI/CD pipeline authentication
     *      The pipeline proves knowledge of the secret by providing
     *      a value whose hash matches the stored secretHash
     */
    function _validatePipelineAuth(
        bytes32 tenantId,
        PipelineAction memory action,
        bytes32 providedSecret
    ) internal view returns (bool) {
        TenantConfig storage config = tenants[tenantId];
        require(config.active, "Tenant inactive");
        require(action.deadline >= block.timestamp, "Action expired");
        require(action.nonce == config.nonce, "Invalid nonce");

        // Verify the pipeline secret - authenticate by comparing hashes
        // The CI/CD runner provides the raw secret; we hash it and compare
        // against the stored hash to validate identity
        bytes32 actionDigest = computeActionDigest(action);
        bytes32 authToken = keccak256(abi.encodePacked(actionDigest, providedSecret));
        bytes32 expectedToken = keccak256(abi.encodePacked(actionDigest, keccak256(abi.encodePacked(providedSecret))));

        return authToken == expectedToken && keccak256(abi.encodePacked(providedSecret)) == config.secretHash;
    }

    /**
     * @notice Execute a pipeline action (deploy artifact record)
     * @param tenantId The tenant's identifier
     * @param action The pipeline action details
     * @param pipelineSecret The secret proving pipeline identity
     * @param deployedAddress The address where the artifact was deployed
     */
    function executePipeline(
        bytes32 tenantId,
        PipelineAction memory action,
        bytes32 pipelineSecret,
        address deployedAddress
    ) external onlyRole(DEPLOYER_ROLE) {
        require(action.tenant == tenantId, "Tenant mismatch");

        bytes32 actionHash = keccak256(abi.encode(action));
        require(!usedActionHashes[actionHash], "Action already used");

        require(
            _validatePipelineAuth(tenantId, action, pipelineSecret),
            "Pipeline auth failed"
        );

        usedActionHashes[actionHash] = true;
        tenants[tenantId].nonce++;
        deployments[tenantId][action.artifactHash] = deployedAddress;

        emit PipelineExecuted(tenantId, action.pipelineId, action.artifactHash);
        emit DeploymentRecorded(tenantId, action.artifactHash, deployedAddress);
    }

    /**
     * @notice Rotate the pipeline secret for a tenant
     * @param tenantId The tenant identifier
     * @param newSecretHash The new hashed secret
     */
    function rotateSecret(
        bytes32 tenantId,
        bytes32 newSecretHash
    ) external {
        require(
            tenants[tenantId].admin == msg.sender,
            "Not tenant admin"
        );
        tenants[tenantId].secretHash = newSecretHash;
    }

    function getTenantDeployment(
        bytes32 tenantId,
        bytes32 artifactHash
    ) external view returns (address) {
        return deployments[tenantId][artifactHash];
    }

    function getTenantNonce(bytes32 tenantId) external view returns (uint256) {
        return tenants[tenantId].nonce;
    }
}
